#include <bits/stdc++.h>
using namespace std;
int n, m, a[100005], now=1;
string b[100005];
int main () {
	cin >> n >> m;
	for (int i=1; i<=n; ++i) 
		cin >> a[i] >> b[i];
	for (int x, s; m--; ) 
		cin >> x >> s,
		now=(now+(a[now]==x?-s:s)+n)%n,
		now=(!now?n:now);
	cout << b[now];
	return 0;
}
